// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != c.owner());
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // In the reference contract, a non-owner call MUST revert.
            // In the buggy version, it will succeed, making the owner change.
            // We assert that the owner remains unchanged.
            assertEq(c.owner(), address(this), "owner changed by non-owner");
        } catch {
            // Revert is expected in the reference contract, so no assertion failure here.
        }
    }
}

